using System;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Net;using System.Net.Http;using System.Net.Sockets;using System.Text;using System.Threading;using System.Threading.Tasks;
internal static class LibraryTests {
 static StringBuilder log=new StringBuilder();static void Check(bool value,string message){if(!value)throw new Exception(message);log.AppendLine("PASS: "+message);}
 internal static int Run(){try{RunAsync().GetAwaiter().GetResult();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"library-test-results.txt"),log.ToString());return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"library-test-results.txt"),log+"FAIL: "+ex);return 1;}}
 static async Task RunAsync(){string root=Path.Combine(Path.GetTempPath(),"CornerPet-LibraryTest-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string db=Path.Combine(root,"store"),cache=Path.Combine(root,"cache"),image=Path.Combine(root,"人物測試.png");string key="共享測試-secret-123456";LibraryServer server=null;
 try{
  string unicodeFolder=Path.Combine(root,"中文 使用者","素材資料夾");var explorer=HostFolders.Prepare(unicodeFolder);Check(Directory.Exists(unicodeFolder)&&File.Exists(explorer.FileName),"folder opener creates missing Unicode directories");Check(!explorer.UseShellExecute&&explorer.Arguments=="\""+Path.GetFullPath(unicodeFolder)+"\"","Explorer receives the full Unicode path as one quoted argument");
  using(var bitmap=new Bitmap(32,24)){using(var g=Graphics.FromImage(bitmap))g.Clear(Color.FromArgb(128,50,180,240));bitmap.Save(image,ImageFormat.Png);}
  server=new LibraryServer(IPAddress.Loopback,0,key,db);int port=server.Port;string address=server.Address;
  using(var client=new LibraryClient(address,key,cache)){
   await client.Ping(CancellationToken.None);Check((await client.List(0,CancellationToken.None)).Total==0,"authenticated connection and empty SQLite catalog");
   using(var wrong=new LibraryClient(address,"wrong-password",cache)){try{await wrong.Ping(CancellationToken.None);throw new Exception("wrong password accepted");}catch(LibraryFailure ex){Check(ex.Code==401,"wrong password is rejected distinctly from offline");}}
   var item=await client.Upload(image,CancellationToken.None);Check(item.Width==32&&item.Height==24&&item.Extension==".png"&&item.Name=="人物測試","image validation and Unicode metadata round trip");var duplicate=await client.Upload(image,CancellationToken.None);Check(duplicate.Id==item.Id&&(await client.List(0,CancellationToken.None)).Total==1,"SHA256 duplicate upload stores one item");
   byte[] thumbnail=await client.Thumbnail(item,CancellationToken.None);using(var ms=new MemoryStream(thumbnail))using(var preview=Image.FromStream(ms))Check(preview.Width==160&&preview.Height==120,"bounded static PNG thumbnails");
   string saved=await client.Download(item,CancellationToken.None);Check(File.Exists(saved)&&LibraryStore.Hash(saved)==item.Id,"download is streamed and SHA256 verified");
   string bad=Path.Combine(root,"fake.gif");File.WriteAllText(bad,"not an image");try{await client.Upload(bad,CancellationToken.None);throw new Exception("invalid image accepted");}catch(LibraryFailure ex){Check(ex.Code==415,"invalid image is rejected without catalog entry");}
   await RejectLargeHeader(port,key);Check((await client.List(0,CancellationToken.None)).Total==1,"rejected upload leaves catalog unchanged");
   string gif=Path.Combine(root,"two.gif");File.WriteAllBytes(gif,new byte[]{71,73,70,56,57,97,1,0,1,0,128,0,0,255,0,0,0,255,0,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,68,1,0,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,76,1,0,59});var animation=await client.Upload(gif,CancellationToken.None);Check(animation.Frames==2&&animation.Extension==".gif","animated GIF is retained, not flattened");
   for(int n=0;n<12;n++){using(var bitmap=new Bitmap(8,8)){using(var g=Graphics.FromImage(bitmap))g.Clear(Color.FromArgb(255,n*15,100,200));bitmap.Save(image,ImageFormat.Png);}await client.Upload(image,CancellationToken.None);}
   var first=await client.List(0,CancellationToken.None);var second=await client.List(1,CancellationToken.None);Check(first.Items.Length==12&&second.Items.Length==2&&first.Total==14,"catalog is paginated at twelve items");
   using(var requestClient=new HttpClient(new HttpClientHandler{UseProxy=false})){requestClient.DefaultRequestHeaders.Add("X-Library-Key",Convert.ToBase64String(Encoding.UTF8.GetBytes(key)));var response=await requestClient.GetAsync(address+"/files/not-an-id");Check(response.StatusCode==HttpStatusCode.NotFound,"arbitrary file paths cannot be downloaded");}
   server.Dispose();server=null;int total;var offline=LibraryClient.LocalPage(cache,0,out total);Check(offline.Length==1&&File.Exists(saved),"downloaded library remains available after host stops");Check(await client.Download(item,CancellationToken.None)==saved,"verified cached item applies without connecting to host");
   try{await client.Ping(CancellationToken.None);throw new Exception("offline host accepted");}catch(HttpRequestException){Check(true,"stopped host reports offline");}catch(OperationCanceledException){Check(true,"unreachable host is bounded by timeout");}
   server=new LibraryServer(IPAddress.Loopback,port,key,db);Check((await client.List(0,CancellationToken.None)).Total==14,"SQLite metadata persists across host restart");
   server.Store.Delete(animation.Id);Check((await client.List(0,CancellationToken.None)).Total==13,"host administrator can delete catalog material");
   using(var requestClient=new HttpClient(new HttpClientHandler{UseProxy=false})){requestClient.DefaultRequestHeaders.Add("X-Library-Key",Convert.ToBase64String(Encoding.UTF8.GetBytes(key)));var response=await requestClient.DeleteAsync(address+"/files/"+item.Id);Check(response.StatusCode==HttpStatusCode.NotFound&&server.Store.Get(item.Id)!=null,"remote client has no delete endpoint");}
   using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();try{await client.List(0,cancelled.Token);throw new Exception("cancel ignored");}catch(OperationCanceledException){Check(true,"requests support cancellation");}}
   var credentials=new LibraryOptions();credentials.Key=key;Check(credentials.Key==key&&!credentials.ProtectedKey.Contains("secret"),"saved shared password is protected with Windows DPAPI");
  }
 }finally{if(server!=null)server.Dispose();try{Directory.Delete(root,true);}catch{}}
 }
 static async Task RejectLargeHeader(int port,string key){using(var socket=new TcpClient()){await socket.ConnectAsync(IPAddress.Loopback,port);using(var stream=socket.GetStream()){string request="POST /assets HTTP/1.1\r\nHost: localhost\r\nX-Library-Key: "+Convert.ToBase64String(Encoding.UTF8.GetBytes(key))+"\r\nContent-Length: "+(LibraryStore.MaxBytes+1)+"\r\n\r\n";byte[] bytes=Encoding.ASCII.GetBytes(request);await stream.WriteAsync(bytes,0,bytes.Length);var read=new byte[4096];int n=await stream.ReadAsync(read,0,read.Length);Check(Encoding.ASCII.GetString(read,0,n).Contains("413"),"oversized upload rejected before buffering body");}}}
}
